<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientClientNameAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientClientNameAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientClientNameAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getClientName returns null on a freshly created holder.
     */
    public function testClientNameNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientClientNameAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isClientNameAssigned());
        $this->assertNull($holder->getClientName());
    }
}
class ImplWithTrustedClientClientNameAttributeHolderUnitTest
{
    use TrustedClientClientNameAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedClientNameRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultClientName();
    }
}
